import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ficha import *
T="IC AGUDA Y EAP"; N=7   # franja roja: vital (por defecto)
note=lambda t: f'<div style="font-size:34px;line-height:1.4;color:{G}">{t}</div>'
rows=lambda *x: '<div style="display:flex;flex-direction:column;gap:20px">'+"".join(x)+'</div>'
P=[
page(1,N,T,big("EDEMA AGUDO DE PULMÓN",128)+big(f'¿FUNCIONA LA FUROSEMIDA? <span style="color:{R}">MÍRALO A LAS 2 HORAS</span>',98)+'<div style="font-size:40px;font-weight:600;line-height:1.3;max-width:820px">Insuficiencia cardiaca aguda: perfil, dosis, respuesta diurética y qué hacer según la presión. Con ficha final.</div>',cover=True),
page(2,N,T,kicker("RECONOCE")+big("CUATRO FORMAS",150,nowrap=True)+rows(line("IC izquierda descompensada"),line("IC derecha descompensada"),line("Edema agudo de pulmón",True),f'<div style="border-top:4px solid {K};padding-top:22px;font-size:42px;font-weight:800;line-height:1.3;color:{R}">Shock cardiogénico: hipoperfusión, lactato &gt; 2 mmol/l</div>')+note("Hipoperfusión no es lo mismo que hipotensión: mira la piel, la consciencia, la diuresis y el lactato.")),
page(3,N,T,kicker("BUSCA LA CAUSA")+big("CHAMPIT",210,R,True)+rows(row("C","Coronario: síndrome coronario agudo"),row("H","Hipertensión: emergencia hipertensiva"),row("A","Arritmia"),row("M","Mecánica: valvulopatía aguda, rotura"),row("P","TEP (Pulmonary embolism)"),row("I · T","Infección · Taponamiento"))+note("NT-proBNP &lt; 300 pg/ml (o BNP &lt; 100) hace improbable el origen cardiaco. Ecografía pulmonar: ≥ 3 líneas B en ≥ 2 espacios intercostales de cada lado.")),
page(4,N,T,kicker("DESCONGESTIONA")+big("FUROSEMIDA IV",150,R,True)+rows(row("Sin diurético previo","40 mg"),row("Si ya lo tomaba","1–2 veces su dosis oral diaria"))+big("¿RESPONDE?",130,nowrap=True)+rows(row("Sodio en orina a las 2 h","&gt; 70 mEq/l"),row("Diuresis a las 6 h","≥ 100–150 ml/h"))+note("Sí: la misma dosis cada 12 h. No: dobla la dosis (bolo máx. 250 mg) y valora acetazolamida, si tomaba dosis bajas, o una tiazida, si tomaba dosis altas.")),
page(5,N,T,kicker("RESPIRA")+big("VMNI PRONTO",180,R,True)+'<div style="font-size:48px;font-weight:800;line-height:1.2">Si FR &gt; 25 y SatO2 &lt; 90 %</div>'+rows(row("CPAP","5–10 cmH2O"),row("BiPAP","Si hay hipercapnia"),row("Oxígeno","Si SatO2 &lt; 90 %, sin hiperoxia"))+note("Si en la primera hora no mejoran la FR ni la oxigenación, intubación. Alto flujo si no tolera la VMNI. Cuidado con la VMNI en el fallo derecho.")),
page(6,N,T,kicker("LA PRESIÓN DECIDE")+big("PAS &gt; 110",150,R,True)+rows(row("Nitroglicerina IV","Inicio 10–20 µg/min"),row("Sube","10–20 µg/min cada 5–10 min"),row("Preparación","25 mg en 500 ml de SG 5 % (10 µg/min = 12 ml/h)"),row("Objetivo","−25 % en 1 h; 130–140 en 6 h"),row("Suspende","Si PAS &lt; 100 o hipotensión"),row("PAS &lt; 90 + hipoperfusión","Dobutamina y UCI"))+note("Morfina: no de rutina. Ansiedad: midazolam 1 mg IV, hasta 3 mg.")),
page(7,N,T,ficha_body("IC AGUDA · EAP","Adulto",[("CAUSA","CHAMPIT: coronario, HTA, arritmia, mecánica, TEP, infección, taponamiento"),("PRUEBAS","NT-proBNP &lt; 300 (BNP &lt; 100): improbable. ECG, troponina, eco"),("FUROSEMIDA","IV 40 mg; si la tomaba, 1–2 veces su dosis oral diaria",True),("¿RESPONDE?","Na orina &gt; 70 mEq/l (2 h) o diuresis ≥ 100–150 ml/h (6 h). Si no: doblar ± acetazolamida o tiazida"),("RESPIRA","O2 si SatO2 &lt; 90 %. VMNI si FR &gt; 25 y SatO2 &lt; 90 % (CPAP 5–10)",True),("PAS","&gt; 110: NTG IV 10–20 µg/min, +10–20 cada 5–10 min (−25 % en 1 h). &lt; 90 e hipoperfusión: dobutamina"),("MORFINA","No de rutina. Ansiedad: midazolam 1–3 mg IV"),("DESTINO","Bajo riesgo (MEESSI-AHF): alta y revisión en 1 semana")],"Consenso ESC-ACVC/HFA/EUSEM 2026 (Miró Ò, et al.); guía ESC 2026",size=112,fs=26),ficha="12"),
]
render(P,sys.argv[1] if len(sys.argv)>1 else "out","ica-eap")
